#include "setup/Payload.h"

#include "core/Module.h"
#include "core/Windows.h"
#include "setup/Resource.h"

#include <fstream>

namespace bw::setup {

namespace {

struct PayloadResource {
    int id;
    const wchar_t* path;
    Existing existing;
};

// Payload.rc (generated by CMakeLists.txt) holds the files; this table says where they go.
constexpr PayloadResource kResources[] = {
    {IDR_PAYLOAD_LAUNCHER, L"BWLaunch.exe", Existing::Replace},
    {IDR_PAYLOAD_DLL, L"BWDecomp.dll", Existing::Replace},
    {IDR_PAYLOAD_INI, L"BWDecomp.ini", Existing::Keep},
    {IDR_PAYLOAD_INI, L"BWDecomp\\BWDecomp.default.ini", Existing::Replace},
    {IDR_PAYLOAD_README, L"BWDecomp\\README.txt", Existing::Replace},
    {IDR_PAYLOAD_CHANGELOG, L"BWDecomp\\CHANGELOG.md", Existing::Replace},
    {IDR_PAYLOAD_FIXES, L"BWDecomp\\FIXES.md", Existing::Replace},
    {IDR_PAYLOAD_RENDERER, L"BWDecomp\\RENDERER.md", Existing::Replace},
    {IDR_PAYLOAD_TEXTURES, L"BWDecomp\\TEXTURES.md", Existing::Replace},
};

std::span<const std::byte> LoadData(int id)
{
    const HRSRC resource = FindResourceW(nullptr, MAKEINTRESOURCEW(id), MAKEINTRESOURCEW(10));  // RT_RCDATA
    const HGLOBAL loaded = resource != nullptr ? LoadResource(nullptr, resource) : nullptr;
    const void* data = loaded != nullptr ? LockResource(loaded) : nullptr;
    if (data == nullptr) {
        throw SetupError(L"Setup is damaged: file " + std::to_wstring(id) + L" is missing. Download it again.");
    }
    return {static_cast<const std::byte*>(data), SizeofResource(nullptr, resource)};
}

}  // namespace

Payload Payload::Load()
{
    Payload payload;
    const std::filesystem::path self = ModulePath(nullptr);
    std::ifstream stream(self, std::ios::binary);
    std::error_code error;
    const std::uintmax_t size = std::filesystem::file_size(self, error);
    payload.m_uninstaller.resize(error ? 0 : static_cast<std::size_t>(size));
    if (error || !stream ||
        !stream.read(reinterpret_cast<char*>(payload.m_uninstaller.data()),
                     static_cast<std::streamsize>(payload.m_uninstaller.size()))) {
        throw SetupError(L"Cannot read " + self.wstring() + L".");
    }
    for (const PayloadResource& resource : kResources) {
        payload.m_files.push_back({resource.path, LoadData(resource.id), resource.existing});
    }
    payload.m_files.push_back({std::wstring(kUninstallerPath), payload.m_uninstaller, Existing::Replace});
    return payload;
}

}  // namespace bw::setup
